/** Every extended name, sorted. */
export const LUCIDE_ICON_NAMES: readonly string[] = Object.keys(LUCIDE_ICON_PATHS);

/** Is this one of the extended (Lucide) icon names? */
export function isLucideIcon(name: string): boolean {
  return Object.prototype.hasOwnProperty.call(LUCIDE_ICON_PATHS, name);
}

/** The `<svg>` for an extended name ('' for anything else), sized to the text. */
export function lucideIconSvg(name: string): string {
  if (!isLucideIcon(name)) return '';
  return (
    '<svg width="1em" height="1em" viewBox="0 0 24 24" fill="none" stroke="currentColor" ' +
    'stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
    LUCIDE_ICON_PATHS[name] +
    '</svg>'
  );
}
